def det(q): return sorted(api.detect_objects(q), key=lambda o: o['distance'])
def held(): return [i['objectId'] for i in api.query_inventory()]
def pick():
    s = det('SaltShaker')
    if s:
        r = api.pickup_object(s[0]['objectId']); print("pick err:", str(r.get('error',''))[:60], held())
    return bool(held())
def face(y):
    for _ in range(4):
        if P()[2] == y: break
        api.rotate('right')

for i in range(4):
    z0 = P()[1]; api.move_ahead()
    if abs(P()[1]-z0) < 0.1 or P()[1] <= -1.5: break
