ok = pick()
if not ok:
    for c in [c for c in det('Cabinet') if c['position']['y'] < 1.2 and c['distance'] < 1.8][:2]:
        if not c['isOpen']: print("open", c['objectId'], str(api.open_object(c['objectId']).get('error',''))[:60])
        if pick(): ok = True; break
if not ok:
    api.look('down'); ok = pick(); api.look('up')
